const STATE_ORDER = {
  'POR HACER': 0,
  'CON IMPEDIMIENTO': 1,
  'LISTO PARA QA': 2,
  'QA': 3,
  'EN CURSO': 4,
  'CODE REVIEW': 5,
  'LISTO PARA DESPLIEGUE': 6,
  'LISTO': 7
};
rows.sort((a, b) => (STATE_ORDER[a.estado] ?? 99) - (STATE_ORDER[b.estado] ?? 99));

const getClosedSprints = (issue, currentSprintId) => {
  if (issue.fields.closedSprints && Array.isArray(issue.fields.closedSprints)) return issue.fields.closedSprints;
  for (const [k, v] of Object.entries(issue.fields)) {
    if (k.startsWith('customfield_') && Array.isArray(v) && v.length > 0) {
      // Detecta sprints anteriores: estado cerrado O id diferente al sprint activo
      const prevSprints = v.filter(s => s && s.name && (s.state === 'closed' || (currentSprintId && s.id !== currentSprintId)));
      if (prevSprints.length > 0) return prevSprints;
    }
  }
  return [];
};

const spilloverData = issues.map(issue => {
  const closed = getClosedSprints(issue, sprintData.id);
  const hasLabel = (issue.fields.labels || []).includes('SprintAnterior');
  if (closed.length === 0 && !hasLabel) return null;
  let sprintOrigen;
  if (closed.length > 0) {
    sprintOrigen = closed[closed.length - 1].name || '-';
  } else {
    const prevNum = parseInt(sprintNumber) - 1;
    sprintOrigen = prevNum ? `Sprint ${prevNum}` : 'Sprint anterior';
  }
  const statusName = issue.fields.status.name;
  const cat = mapStatus(statusName);
  const catObj = CATEGORIES.find(c => c.key === cat);
  return { key: issue.key, titulo: issue.fields.summary, sprintOrigen, estado: cat, color: catObj.color, bg: catObj.bg };
}).filter(Boolean);

