const spilloverHtml = spilloverCount > 0 ? `<div style='padding:0 20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #F59E0B;'><tr><td style='padding:20px 24px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#F59E0B; margin-bottom:4px;'>🔄 SPILLOVER</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:15px; color:#1E293B; margin-bottom:16px;'><strong>${spilloverCount}</strong> ticket${spilloverCount > 1 ? 's' : ''} arrastrado${spilloverCount > 1 ? 's' : ''} de sprints anteriores <span style='color:#64748B;'>(${spilloverRate}% del sprint)</span></div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEF3C7;'><th align='left' style='padding:8px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Ticket</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Título</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Sprint Origen</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Estado Actual</th></tr></thead><tbody>${spilloverRows}</tbody></table></td></tr></table></div>` : '';

const escapedRows = escapedDefects.map(e => `<tr><td style='padding:8px 16px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;'>${e.key}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;'>${e.titulo}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569; white-space:nowrap;'>${e.estado}</td></tr>`).join('');

const escapedHtml = escapedCount > 0 ? `<div style='padding:0 20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #DC2626;'><tr><td style='padding:20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0'><tr><td valign='top'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#DC2626; margin-bottom:4px;'>🐛 ESCAPED DEFECTS — ENCONTRADOS EN PRODUCCIÓN</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#64748B; margin-bottom:16px;'>Bugs con etiqueta <strong style='color:#1E293B;'>Producción_PortalPacientes</strong> en el sprint activo</div></td><td valign='top' style='text-align:right; width:60px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:36px; font-weight:700; color:#DC2626; line-height:1;'>${escapedCount}</div></td></tr></table><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEE2E2;'><th align='left' style='padding:8px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Ticket</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Título</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Estado</th></tr></thead><tbody>${escapedRows}</tbody></table></td></tr></table></div>` : '';

const body = `<div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background-color:${headerColor};'><tr><td style='padding:28px 28px;' valign='top'><div style='color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;'>Reporte Automático · Board PP</div><div style='color:#FFFFFF; font-size:22px; font-weight:700; margin-top:8px;'>📊 Sprint ${sprintNumber}${sprintData.goal ? ' — ' + sprintData.goal : ''}</div><div style='color:#CFE2FF; font-size:13px; margin-top:6px;'>Periodo: ${fechaInicio} al ${fechaFin}</div>${headerBadge}</td></tr></table>${progressHtml}<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='padding:12px 20px;'><tr>${cardsRow1}</tr><tr>${cardsRow2}</tr></table>${qaBlockHtml}${escapedHtml}${spilloverHtml}<div style='padding:0 20px 24px; overflow-x:auto;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);'><thead><tr style='background:#0747A6;'><th align='left' width='90' style='padding:10px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF; white-space:nowrap; width:90px;'>Ticket</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Tipo</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Título</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Estado Actual</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF; white-space:nowrap;'>Asignado a</th><th align='center' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Alertas</th></tr></thead><tbody>${tableRows}</tbody></table></div><div style='padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;'>Generado automáticamente — WF1 Status Sprint en Curso · ${new Date().toLocaleString('es-CL', { dateStyle: 'short', timeStyle: 'short' })}</div></div>`;

// Teams Adaptive Card
const ticketColumnSets = (() => {
  const result = [];
  for (const section of PRIORITY_SECTIONS) {
    const sRows = rows.filter(r => getPriorityGroup(r.priority) === section.group);
    if (sRows.length === 0) continue;
    result.push({ type: 'TextBlock', text: section.label, weight: 'bolder', size: 'small', color: section.teamColor, spacing: 'medium' });
    result.push({ type: 'ColumnSet', columns: [
      { type: 'Column', width: 'auto', items: [{ type: 'TextBlock', text: 'Ticket', weight: 'bolder', size: 'small', isSubtle: true }] },
      { type: 'Column', width: 'stretch', items: [{ type: 'TextBlock', text: 'Estado  ·  Asignado', weight: 'bolder', size: 'small', isSubtle: true }] }
    ]});
    for (const r of sRows) {
      result.push(
        { type: 'ColumnSet', separator: true, columns: [
          { type: 'Column', width: 'auto', items: [{ type: 'TextBlock', text: r.key, color: 'accent', weight: 'bolder', size: 'small', wrap: false }] },
          { type: 'Column', width: 'stretch', items: [{ type: 'TextBlock', text: `${r.estado}  ·  ${r.asignado}${r.alerta ? '  ' + r.alerta : ''}`, size: 'small', wrap: true, isSubtle: true }] }
        ]},
        { type: 'TextBlock', text: r.titulo, size: 'small', wrap: true, spacing: 'none' }
      );
    }
  }
  return result;
})();

const teamsCard = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    contentUrl: null,
    content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
      type: 'AdaptiveCard',
      version: '1.5',
      body: [
        {
          type: 'Container',
          style: enRiesgo ? 'attention' : 'accent',
          bleed: true,
          items: [
            { type: 'TextBlock', text: 'Reporte Automático · Board PP', size: 'small', weight: 'bolder', spacing: 'none' },
            { type: 'TextBlock', text: `📊 Sprint ${sprintNumber}${sprintData.goal ? ' — ' + sprintData.goal : ''}`, size: 'large', weight: 'bolder', spacing: 'small' },
            { type: 'TextBlock', text: `Periodo: ${fechaInicio} al ${fechaFin}`, spacing: 'none', isSubtle: true },
            ...(enRiesgo ? [{ type: 'TextBlock', text: `🚨 SPRINT EN RIESGO — ${diasLabel} · ${pctPendiente}% pendiente`, weight: 'bolder', size: 'medium', spacing: 'small' }] : [])
          ]
        },
        {
          type: 'Container',
          spacing: 'medium',
          items: [
            { type: 'TextBlock', text: `📊 Progreso del Sprint · ${diasLabel}`, weight: 'bolder', color: diasRestantes <= 2 ? 'attention' : 'default' },
            { type: 'TextBlock', text: `✅ ${pctCompletado}% completado  ·  🔄 ${pctEnProgreso}% en progreso  ·  ⏳ ${pctPendiente}% pendiente${conImpedimento > 0 ? `  ·  🚫 ${pctImpedimento}% con impedimento` : ''}`, wrap: true, spacing: 'small' }
          ]
        },
        {
          type: 'Container',
          spacing: 'medium',
          items: [
            { type: 'TextBlock', text: 'Estado del Sprint', weight: 'bolder' },
            {
              type: 'ColumnSet',
              spacing: 'small',
              columns: CATEGORIES.slice(0, 4).map(cat => ({
                type: 'Column', width: 'stretch',
                items: [
                  { type: 'TextBlock', text: `${counts[cat.key]}`, size: 'extraLarge', weight: 'bolder', horizontalAlignment: 'center', spacing: 'none' },
                  { type: 'TextBlock', text: cat.key, size: 'small', horizontalAlignment: 'center', wrap: true, spacing: 'none', isSubtle: true }
                ]
              }))
            },
            {
              type: 'ColumnSet',
              spacing: 'small',
              columns: CATEGORIES.slice(4, 8).map(cat => ({
                type: 'Column', width: 'stretch',
                items: [
                  { type: 'TextBlock', text: `${counts[cat.key]}`, size: 'extraLarge', weight: 'bolder', horizontalAlignment: 'center', spacing: 'none' },
                  { type: 'TextBlock', text: cat.key, size: 'small', horizontalAlignment: 'center', wrap: true, spacing: 'none', isSubtle: true }
                ]
              }))
            }
          ]
        },
        {
          type: 'Container',
          style: ticketsEsperandoQA > 5 ? 'attention' : ticketsEsperandoQA > 2 ? 'warning' : 'good',
          spacing: 'medium',
          items: [{
            type: 'ColumnSet',
            columns: [
              {
                type: 'Column', width: 'stretch',
                items: [
                  { type: 'TextBlock', text: '🧪 CARGA QA ACTUAL', weight: 'bolder', size: 'medium' },
                  { type: 'TextBlock', text: `${counts['LISTO PARA QA']} esperando QA  ·  ${counts['QA']} en QA actualmente`, wrap: true, spacing: 'none' }
                ]
              },
              {
                type: 'Column', width: 'auto',
                items: [
                  { type: 'TextBlock', text: `${ticketsEsperandoQA}`, size: 'extraLarge', weight: 'bolder', horizontalAlignment: 'right' },
                  { type: 'TextBlock', text: 'tickets pendientes QA', size: 'small', horizontalAlignment: 'right', spacing: 'none', isSubtle: true }
                ]
              }
            ]
          }]
        },
        ...(escapedCount > 0 ? [{
          type: 'Container', style: 'attention', spacing: 'medium',
          items: [
            { type: 'TextBlock', text: `🐛 ESCAPED DEFECTS — ${escapedCount} encontrado${escapedCount > 1 ? 's' : ''} en producción`, weight: 'bolder' },
            ...escapedDefects.map(e => ({ type: 'TextBlock', text: `• **${e.key}**: ${e.titulo}`, wrap: true, size: 'small', spacing: 'small' }))
