            ...ticketColumnSets
          ]
        },
        {
          type: 'TextBlock', spacing: 'medium', isSubtle: true, size: 'small',
          text: `Generado automáticamente — WF1 Status Sprint en Curso · ${new Date().toLocaleString('es-CL', { dateStyle: 'short', timeStyle: 'short' })}`
        }
      ]
    }
  }]
};

return [{ json: { subject, body, teamsPayload: JSON.stringify(teamsCard) } }];
